//! VIE vectors generated by running the reference server's VIE module (ASSS
//! `enc_vie.c`, compiled unmodified): key exchange, keystream tables and
//! per-packet encryption for edge-case and random keys.

use oss_net::VieCipher;
use oss_net::cipher::{Accept, Acceptor, Handshake, Step, VieAcceptor, VieClientHandshake};

const VECTORS: &str = include_str!("vectors/vie.txt");

fn hex(s: &str) -> Vec<u8> {
    if s == "-" {
        return Vec::new();
    }
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn records(tag: &'static str) -> impl Iterator<Item = Vec<&'static str>> {
    VECTORS
        .lines()
        .filter(|l| !l.starts_with('#'))
        .map(|l| l.split_whitespace().collect::<Vec<_>>())
        .filter(move |f| f.first() == Some(&tag))
}

fn key(s: &str) -> u32 {
    u32::from_str_radix(s, 16).unwrap()
}

#[test]
fn key_exchange() {
    let mut n = 0;
    for f in records("keyexchange") {
        let (client_key, request, response) = (key(f[1]), hex(f[2]), hex(f[3]));
        // The server answers the request with exactly the reference response.
        let mut out = Vec::new();
        let accepted = VieAcceptor {
            accept_continuum: false,
        }
        .accept(0, &request, &mut out);
        assert!(
            matches!(accepted, Some(Accept::Established(_))),
            "key {client_key:#x}"
        );
        assert_eq!(out, [response.clone()], "key {client_key:#x}");
        // Our client builds the same request for that key and accepts the response.
        let mut hs = VieClientHandshake::with_key(client_key, 1);
        let mut sent = Vec::new();
        hs.poll(0, &mut sent);
        assert_eq!(sent[0], request);
        assert!(matches!(
            hs.on_datagram(0, &response, &mut sent),
            Step::Established(_)
        ));
        n += 1;
    }
    assert_eq!(n, 16);
}

#[test]
fn client_state_edge_cases() {
    // How a client should treat each server key. Two keys differ from the
    // reference server's own client code; we follow the server (see
    // docs/protocol/encryption.md):
    // - client key 1 -> server key -1 (0xFFFFFFFF): the reference client mistakes
    //   it for its "bad key" sentinel and runs unencrypted, but the server
    //   encrypts. We encrypt.
    // - client key 0x80000000 -> its negation is itself, so the response looks
    //   like "no encryption" to a client, yet the reference server encrypts. A
    //   client must never use that key; ours never does.
    for f in records("keyexchange") {
        let client_key = key(f[1]);
        let server_key = client_key.wrapping_neg();
        let mut hs = VieClientHandshake::with_key(client_key, 1);
        let resp = hex(f[3]);
        let Step::Established(c) = hs.on_datagram(0, &resp, &mut Vec::new()) else {
            panic!()
        };
        let expect_vie = server_key != 0 && server_key != client_key;
        assert_eq!(
            c.name(),
            if expect_vie { "vie" } else { "none" },
            "key {client_key:#x}"
        );
    }
    // The server side encrypts for 0x80000000 as the reference does.
    let mut out = Vec::new();
    let req = [0, 1, 0, 0, 0, 0x80, 1, 0];
    let Some(Accept::Established(c)) = VieAcceptor::default().accept(0, &req, &mut out) else {
        panic!()
    };
    assert_eq!(c.name(), "vie");
    assert_eq!(oss_net::vie::client_key_from_seed(0), 0x8000_0001);
}

#[test]
fn tables() {
    let mut n = 0;
    for f in records("table") {
        let k = key(f[1]);
        match VieCipher::new(k) {
            None => assert_eq!(f[2], "-"),
            Some(c) => assert_eq!(c.table_bytes().to_vec(), hex(f[2]), "table for {k:#x}"),
        }
        n += 1;
    }
    assert_eq!(n, 16);
}

#[test]
fn encrypt_and_decrypt() {
    let mut n = 0;
    for (tag, decrypt) in [("encrypt", false), ("decrypt", true)] {
        for f in records(tag) {
            let k = key(f[1]);
            let (input, output) = (hex(f[2]), hex(f[3]));
            let mut buf = input.clone();
            if let Some(c) = VieCipher::new(k) {
                if decrypt {
                    c.decrypt(&mut buf);
                } else {
                    c.encrypt(&mut buf);
                }
            }
            assert_eq!(buf, output, "{tag} key {k:#x} input {}", f[2]);
            n += 1;
        }
    }
    assert_eq!(n, 2 * 768);
}
